{
  "data_file": "microsoft.csv",
  "analysis_methods": [
    {
      "id": 71,
      "question": "Calculate the mean and standard deviation of the \"Volume\" column.",
      "constraints": "Use the built-in functions in Python's pandas library for computation. Round the result to 2 decimal places.",
      "format": "@mean_volume[mean_volume]\\n@std_dev_volume[std_dev_volume]\\nwhere \"mean_volume\" and \"std_dev_volume\" are floating-point numbers rounded to 2 decimal places."
    },
    {
      "id": 72,
      "question": "Check if the \"Close\" column adheres to a normal distribution.",
      "constraints": "Use the Shapiro-Wilk test to assess the normality of the \"Close\" column. If the p-value is less than 0.05, consider the data to be non-normally distributed. Otherwise, consider it to be normally distributed.",
      "format": "@normality_test_result[normality_test_result]\\nwhere \"normality_test_result\" a string that is either \"Normal\" or \"Non-normal\" based on the p-value from the Shapiro-Wilk test."
    },
    {
      "id": 73,
      "question": "Calculate the correlation coefficient between the \"High\" and \"Low\" columns.",
      "constraints": "Use the Pearson correlation coefficient for computation. Round the result to 2 decimal places.",
      "format": "@correlation_coefficient[correlation_coefficient]\\nwhere \"correlation_coefficient\" is a floating-point number rounded to 2 decimal places."
    },
    {
      "id": 77,
      "question": "Perform comprehensive data preprocessing on the \"Date\" column to extract the month and year information. Calculate the average closing price for each month and year combination. Return the month and year combination which has the highest average closing price.",
      "constraints": "Set the start of each month to be the first day of the month and the end of the month to be the last day of the month.\nThe calculation of the average closing price should be done using the arithmetic mean. \nFor ties, return the most recent month and year combination.",
      "format": "@Highest_Monthly_Average_Close_Price[month, year, average_close_price]\nwhere \"month\" is an integer between 1 and 12, \"year\" is an integer, and \"average_close_price\" is a float rounded to two decimal places."
    }
  ],
  "format_scope": "Original format fields specify result identities and numeric precision. The current deliverable is a natural-language report; the upstream @field[value] syntax is not required."
}

